"use strict";

/**
 * The decision records in a LangGraph BaseStore (InMemoryStore, PostgresStore, …), with the three calls
 * the gate makes on them. Do not edit this file.
 *
 *   persist(key, record)  adds a record under the key. Never overwrites, never deletes.
 *   list(key)             every record under the key, oldest first.
 *   load(key)             the latest record under the key that executed (spec 5.2), or null.
 *
 * Records go under ["preflight", area, <the key>], each as its own item, named by when it was written
 * and a count, so that the names in order are the order written. A namespace label may hold no ":" or
 * ".": the key is written there percent-encoded.
 *
 * The store itself allows an item to be overwritten or deleted; this file does neither. Keeping records
 * the agent cannot rewrite (spec 8.2) is the store's and yours: do not hand this store to the agent
 * (createAgent's store), where tools and other middleware reach it.
 */

const PAGE = 100;
let written = 0;
const label = key => encodeURIComponent(String(key ?? "UNKEYED")).replace(/\./g, "%2E");
const itemName = () => `${new Date().toISOString()}#${String(++written).padStart(12, "0")}#${Math.random().toString(36).slice(2, 8)}`;

function recordStore(base, area = "records") {
  if (!base || typeof base.put !== "function" || typeof base.search !== "function") throw new Error("recordStore: a LangGraph BaseStore is required");
  const ns = key => ["preflight", area, label(key)];
  async function list(key) {
    const items = [];
    for (let offset = 0; ; offset += PAGE) {
      const page = await base.search(ns(key), { limit: PAGE, offset });
      items.push(...page.filter(it => it.namespace.length === 3));
      if (page.length < PAGE) break;
    }
    return items.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0)).map(it => it.value.record);
  }
  return {
    async persist(key, record) {
      await base.put(ns(key), itemName(), { record });
      return record;
    },
    list,
    async load(key) {
      const all = await list(key);
      for (let i = all.length - 1; i >= 0; i--) if (all[i]?.execution_decision === "executed") return all[i];
      return null;
    },
  };
}

module.exports = { recordStore };
